INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-cop31-collapse-uk-reaction', 'cop31-antalya-climate-talks-collapse-uk-eu-reject-deal-fossil-fuels', 'newsroom', 'news_story', 'uk', 'EDITORIAL_REVIEW', 0, 'COP31 climate talks collapse as UK and EU reject deal that left out fossil fuels', 'Energy Secretary Miatta Fahnbulleh called the outcome "immensely disappointing" after the longest COP on record ended in Antalya without an agreement.', 'The COP31 United Nations climate summit in Antalya, Turkey, ended on Sunday, Nov. 22, without an overall agreement. Countries including the UK and EU members refused to accept a final text that did not mention fossil fuels, according to reporting by The Independent and CNBC.

The talks ran almost two days past their scheduled finish, making COP31 the longest climate summit on record. Turkey''s environment minister Murat Kurum, the conference president, told the closing session he could see there was no agreement and said he would not put forward a new draft.

## Why it fell apart

The dispute was over whether the text should mention oil, gas and coal at all. The draft instead called for faster development of carbon-removal technology, an approach pushed by Saudi Arabia, The Independent reported. The EU, the UK and small island states such as Tuvalu rejected it. Developing countries also said it offered too little new money to help them adapt to climate change.

Australia''s Chris Bowen, who led the negotiations alongside Turkey, said fossil fuels and climate finance were the dealbreakers.

## The UK response

Energy Secretary Miatta Fahnbulleh called the failure "immensely disappointing," but said there had been genuine progress, The Independent reported. A UK delegation spokesperson said Britain was profoundly disappointed by the proposed text.

Prime Minister Andy Burnham was the only G7 leader to attend the summit in person. In his speech on Nov. 12 he promised a new era of British climate leadership and announced a £5 billion private clean-energy finance programme, S&P Global reported.

## What survives

Some smaller agreements did go through, including a target to raise electricity''s share of global energy use to 35% by 2035, which the UK had endorsed. Commitments made at earlier summits remain in force.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Barrow_Offshore_wind_turbines_NR.jpg/1280px-Barrow_Offshore_wind_turbines_NR.jpg', 'Barrow Offshore Wind turbines off Walney Island in the Irish Sea (file photo). Photo by Muhammad Mahdi Karim via Wikimedia Commons; editor to confirm the license on the file page', 'licensed', 'newsroom', 'content/2026-11-23-uk.sql', 7, 0, 'newsroom-assistant', '2026-11-24T01:45:00.000Z', '2026-11-24T01:45:00.000Z');
