INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-poundland-deadline', 'poundland-rescue-deadline-wednesday-zachert-bid-11000-jobs-600-shops', 'newsroom', 'news_story', 'uk', 'EDITORIAL_REVIEW', 0, 'Poundland races Wednesday deadline as a new bidder emerges and 11,000 jobs hang in the balance', 'German firm Zachert Private Equity has made a late offer, while owner Gordon Brothers met Business Secretary Jonathan Reynolds on Monday.', 'Poundland has until midnight on Wednesday, Nov. 25, to agree a rescue deal or face administration, putting about 11,000 jobs and 600 UK shops at risk, the Press Association reported.

The discount chain filed a first notice of intention to appoint administrators at the end of October. When it expired, Poundland filed a second notice earlier this month, giving it another 10 working days of protection from creditors. That second window is the one closing this week.

## A late bidder

German investment firm Zachert Private Equity lodged an indicative takeover proposal over the weekend with advisers to Poundland''s owner, Gordon Brothers, Sky News reported, according to The Grocer. It joins earlier interest from Martin Property Group, which is backed by Poundland''s management, and Xyra Group Holdings.

The Grocer reported that neither of those two bidders is thought to have agreed to Gordon Brothers'' demand that a £30 million shareholder loan be repaid upfront, and that Xyra had yet to show proof of funding. How Zachert would fund a deal is also unclear, the Press Association reported.

Tesco has held talks about buying up to 150 shops, and Iceland and Lidl have also been linked to parts of the estate.

## Government involvement

Gordon Brothers met Business Secretary Jonathan Reynolds again on Monday, Nov. 23, to update him on the sale, according to the Press Association. MPs have accused the owner of deliberately cutting off funds, and Prime Minister Andy Burnham has urged executives to work with the government to save shops and jobs.

If no deal is reached, advisory firm AlixPartners is expected to be appointed administrator. The chain also faces pressure to fund stock for the Christmas trading period.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Fomer_Wilko_store_in_Chester_became_Poundland.jpg/1280px-Fomer_Wilko_store_in_Chester_became_Poundland.jpg', 'A Poundland shop on Foregate Street, Chester, in a former Wilko store (file photo). Via Wikimedia Commons (CC0 public domain dedication); editor to confirm on the file page', 'public_domain', 'newsroom', 'content/2026-11-23-uk.sql', 7, 0, 'newsroom-assistant', '2026-11-24T01:45:00.000Z', '2026-11-24T01:45:00.000Z');
